python -c "
import json, zlib, base64, io, pandas as pd, numpy as np

def load_signal(path):
    with open(path) as fh:
        d = json.load(fh)
    art = d['validation']['signal_artifact']
    raw = base64.b64decode(art['data'])
    csv = zlib.decompress(raw).decode()
    df = pd.read_csv(io.StringIO(csv))
    df = df.apply(pd.to_numeric, errors='coerce')
    return df

dfs = {}
for f in ['mom_10d_skip5','mom_120d_skip5','vix_beta_cond_60x20','vol_of_vol20x60']:
    dfs[f] = load_signal(f'factors/{f}.json')

names = list(dfs.keys())
print('shapes:', {k: v.shape for k, v in dfs.items()})

def corr_panel(a, b, tail=400):
    A = a.tail(tail).values.ravel(); B = b.tail(tail).values.ravel()
    m = ~(np.isnan(A) | np.isnan(B))
    if m.sum() < 50: return np.nan
    return np.corrcoef(A[m], B[m])[0,1]

def mean_xs_corr(a, b, tail=400):
    A = a.tail(tail).values; B = b.tail(tail).values
    cs = []
    for ra, rb in zip(A, B):
        m = ~(np.isnan(ra) | np.isnan(rb))
        if m.sum() >= 8:
            c = np.corrcoef(ra[m], rb[m])[0,1]
            if not np.isnan(c): cs.append(c)
    return np.mean(cs) if cs else np.nan

print('Pooled corr (last 400 rows):')
for i in range(len(names)):
    for j in range(i+1, len(names)):
        print(f'  {names[i]:22s} vs {names[j]:22s}: {corr_panel(dfs[names[i]], dfs[names[j]]):+.3f}')
print('Mean cross-sectional corr (last 400 rows):')
for i in range(len(names)):
    for j in range(i+1, len(names)):
        print(f'  {names[i]:22s} vs {names[j]:22s}: {mean_xs_corr(dfs[names[i]], dfs[names[j]]):+.3f}')
"

